def count_paths_N(N):
    """Calculates the number of good paths for an N x N board filled monotonically row-by-row."""

    # Grid setup: N(i, j) = (i - 1) * N + j, where 1 <= i, j <= N

    # Adjacency function: Returns valid neighbors of (r, c) [1-indexed]
    def get_neighbors(r, c):
        neighbors = []
        potential_coords = [
            (r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)
        ]

        for nr, nc in potential_coords:
            if 1 <= nr <= N and 1 <= nc <= N:
                neighbors.append((nr, nc))
        return neighbors

    # Value at coordinate (r, c)
    def value(r, c):
        return (r - 1) * N + c

    memo = {}

    def count_paths_from_coords(r, c):
        if (r, c) in memo:
            return memo[(r, c)]

        current_val = value(r, c)

        # Start count: 1 (the path consisting only of the current field)
        total_count = 1

        # Find neighbors X such that X > current_val
        outgoing_neighbors_coords = []
        for nr, nc in get_neighbors(r, c):
            neighbor_val = value(nr, nc)
            if neighbor_val > current_val:
                outgoing_neighbors_coords.append((nr, nc))

        # Sum up path counts originating from outgoing neighbors
        for nr, nc in outgoing_neighbors_coords:
            total_count += count_paths_from_coords(nr, nc)

        memo[(r, c)] = total_count
        return total_count

    # The starting point is always (1, 1) in the monotonic fill
    if N == 0:
        return 0

    return count_paths_from_coords(1, 1)

# Test N=2
N2_paths = count_paths_N(2)
print(f"Path count for N=2 (Monotonic Fill): {N2_paths}")
